    "source": "import java.util.*;\n\npublic class ArrayLesson {\n  private static final List<String> frames = new ArrayList<>();\n\n  static int solve(int[] a, long target) {\n    if (target <= 0) throw new IllegalArgumentException(\"Positive target required\");\n    for (int v : a) if (v < 0) throw new IllegalArgumentException(\"Nonnegative values required\");\n    long sum = 0;\n    int left = 0, best = Integer.MAX_VALUE;\n    for (int right = 0; right < a.length; right++) {\n      sum += a[right];\n      emit(\"Expand right; window sum becomes \" + sum + \".\", a, left, right);\n      while (sum >= target) {\n        best = Math.min(best, right - left + 1);\n        sum -= a[left++];\n        emit(\"Record a valid window, then shrink; best length is \" + best + \".\", a, right);\n      }\n    }\n    return best == Integer.MAX_VALUE ? 0 : best;\n  }\n\n  // Teaching support: snapshots never participate in the algorithm's decisions.\n  static void emit(String note, int[] values, int... active) {\n    frames.add(\"{\\\"note\\\":\" + json(note) + \",\\\"values\\\":\" + json(values)\n        + \",\\\"active\\\":\" + json(active) + \"}\");\n  }\n\n  static String json(Object value) {\n    if (value == null) return \"null\";\n    if (value instanceof Number || value instanceof Boolean) return value.toString();\n    if (value.getClass().isArray()) {\n      List<String> parts = new ArrayList<>();\n      for (int i = 0; i < java.lang.reflect.Array.getLength(value); i++)\n        parts.add(json(java.lang.reflect.Array.get(value, i)));\n      return \"[\" + String.join(\",\", parts) + \"]\";\n    }\n    if (value instanceof Collection<?> items) {\n      List<String> parts = new ArrayList<>();\n      for (Object item : items) parts.add(json(item));\n      return \"[\" + String.join(\",\", parts) + \"]\";\n    }\n    return \"\\\"\" + value.toString().replace(\"\\\\\", \"\\\\\\\\\")\n        .replace(\"\\\"\", \"\\\\\\\"\").replace(\"\\n\", \"\\\\n\") + \"\\\"\";\n  }\n\n  public static void main(String[] args) {\n    Object result = solve(new int[] {2, 3, 1, 2, 4, 3}, 7);\n    if (args.length > 0 && args[0].equals(\"--trace\"))\n      for (String frame : frames) System.out.println(\"TRACE\\t\" + frame);\n    System.out.println(json(result));\n  }\n}\n",
